package com.afterglow.player;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.util.zip.*;
public class StemChecks extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}void waitDone()throws Exception{Thread.sleep(1500);for(int i=0;i<600&&StemService.busy;i++)Thread.sleep(1000);if(StemService.busy)throw new Exception("Stem worker timed out");}
 public void onStart(){Bundle result=new Bundle();File fixture=new File(getTargetContext().getCacheDir(),"stem-test-demo.wav");try{try(InputStream in=getTargetContext().getAssets().open("demo.wav");RandomAccessFile out=new RandomAccessFile(fixture,"rw")){out.setLength(0);byte[] header=new byte[44];new DataInputStream(in).readFully(header);out.write(header);int bytes=22050*12*2;out.seek(4);out.writeInt(Integer.reverseBytes(36+bytes));out.seek(40);out.writeInt(Integer.reverseBytes(bytes));byte[] buffer=new byte[8192];int left=bytes;while(left>0){int n=in.read(buffer,0,Math.min(left,buffer.length));if(n<0)throw new EOFException();out.write(buffer,0,n);left-=n;}}startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));getTargetContext().startForegroundService(new Intent(getTargetContext(),StemService.class).setAction("test"));waitDone();if(!StemService.status.startsWith("Connected"))throw new Exception(StemService.status);getTargetContext().startForegroundService(new Intent(getTargetContext(),StemService.class).setAction("separate").putExtra("uri",android.net.Uri.fromFile(fixture).toString()).putExtra("title","Original Afterglow test demo"));waitDone();if(!StemService.status.startsWith("Four stems ready"))throw new Exception(StemService.status+" · "+StemService.diagnostic);try(ZipFile zip=new ZipFile(StemService.output(getTargetContext()))){ZipEntry v=zip.getEntry("vocals.wav"),i=zip.getEntry("drums.wav");if(zip.getEntry("bass.wav")==null||zip.getEntry("other.wav")==null)throw new Exception("Missing four stems");if(v==null||i==null||v.getSize()<1000000||i.getSize()<1000000)throw new Exception("Missing full WAV stems");if(v.getCrc()==i.getCrc())throw new Exception("Identical stems");result.putString("result","PASS: server connection, audio upload, real four-stem Demucs inference, result download and export ZIP");}fixture.delete();finish(Activity.RESULT_OK,result);}catch(Throwable e){fixture.delete();result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}}
}
